const WORKFLOW_VERSION = 'ssot-v6';
const RENDERER_VERSION = 'figma-tree-v4';
const MAX_COMPONENTS_PER_RUN = (() => {
  const raw = String($env.MAX_COMPONENTS_PER_RUN || '').trim();
  if (!raw) return Infinity;
  const value = Number(raw);
  return Number.isFinite(value) && value > 0 ? Math.floor(value) : Infinity;
})();
const MCP_ENDPOINT = 'http://127.0.0.1:3101/mcp';
const CANONICAL_TOKEN_KEYS = new Set(['core', 'semantic', 'typography', 'component']);
const REVIEW_BRANCH_SCAN_LIMIT = 12;

function isObject(value) {
  return !!value && typeof value === 'object' && !Array.isArray(value);
}

function isTokenNode(node) {
  return isObject(node) && ('value' in node || '$value' in node);
}

function toCamelSegment(segment) {
  return String(segment).replace(/-([a-z0-9])/gi, (_, char) => char.toUpperCase());
}

function normalizeTokenReference(value) {
  if (typeof value !== 'string') return value;
  const match = value.trim().match(/^\{(.+)\}$/);
  if (!match) return value;
  return `{${match[1].split('.').filter(Boolean).map(toCamelSegment).join('.')}}`;
}

function normalizeTokenTree(node) {
  if (!isObject(node)) return node;
  if (isTokenNode(node)) {
    const output = { value: normalizeTokenReference(node.value ?? node.$value) };
    if (node.type || node.$type) output.type = node.type ?? node.$type;
    if (node.description || node.$description) output.description = node.description ?? node.$description;
    return output;
  }

  const output = {};
  for (const [rawKey, value] of Object.entries(node)) {
    if (rawKey === '$extensions') continue;
    const key = rawKey.startsWith('$') ? rawKey : toCamelSegment(rawKey);
    output[key] = normalizeTokenTree(value);
  }
  return output;
}

function mergeTokenTree(target, source) {
  if (!isObject(source)) return target;
  for (const [key, value] of Object.entries(source)) {
    if (isObject(value) && isObject(target[key]) && !isTokenNode(value) && !isTokenNode(target[key])) {
      mergeTokenTree(target[key], value);
    } else {
      target[key] = value;
    }
  }
  return target;
}

function readTokenSet(rawTokens, setPath) {
  if (!isObject(rawTokens)) return null;
  if (rawTokens[setPath]) return rawTokens[setPath];
  return setPath.split('/').filter(Boolean).reduce((current, segment) => {
    if (!isObject(current) || !current[segment]) return null;
    return current[segment];
  }, rawTokens);
}

function normalizeDesignTokens(rawTokens) {
  const normalized = {};
  if (rawTokens?.$metadata) normalized.$metadata = rawTokens.$metadata;

  for (const key of CANONICAL_TOKEN_KEYS) {
    if (isObject(rawTokens?.[key])) normalized[key] = normalizeTokenTree(rawTokens[key]);
  }

  const primitive = readTokenSet(rawTokens, 'Primitive/Value') || readTokenSet(rawTokens, 'primitive/value');
  const space = readTokenSet(rawTokens, 'Space/Value') || readTokenSet(rawTokens, 'space/value');
  const radius = readTokenSet(rawTokens, 'Radius/Value') || readTokenSet(rawTokens, 'radius/value');
  const typography = readTokenSet(rawTokens, 'Typography/Value') || readTokenSet(rawTokens, 'typography/value');
  const semantic = readTokenSet(rawTokens, 'Semantic/Dark') || readTokenSet(rawTokens, 'semantic/dark');
  const component = readTokenSet(rawTokens, 'Component/Value') ||
    readTokenSet(rawTokens, 'component/value') ||
    readTokenSet(rawTokens, 'component/component');

  if (primitive) mergeTokenTree(normalized.core ||= {}, normalizeTokenTree(primitive));
  if (space?.space) mergeTokenTree(normalized.core ||= {}, { space: normalizeTokenTree(space.space) });
  if (radius?.radius) mergeTokenTree(normalized.core ||= {}, { radius: normalizeTokenTree(radius.radius) });
  if (typography?.font) mergeTokenTree(normalized.core ||= {}, { font: normalizeTokenTree(typography.font) });
  if (typography?.typography) normalized.typography = normalizeTokenTree(typography.typography);
  if (semantic) normalized.semantic = normalizeTokenTree(semantic);
  if (component) normalized.component = normalizeTokenTree(component);

  return normalized;
}

function stableStringify(value) {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(',')}]`;
  }

  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(',')}}`;
  }

  return JSON.stringify(value ?? null);
}

function simpleHash(value) {
  const input = typeof value === 'string' ? value : stableStringify(value);
  let hash = 2166136261;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

function getNodeByPath(root, path) {
  return String(path || '')
    .split('.')
    .filter(Boolean)
    .reduce((current, key) => {
      if (!current || typeof current !== 'object') {
        return undefined;
      }
      return current[key];
    }, root);
}

function componentConfigForHash(componentSnapshot) {
  if (!isObject(componentSnapshot)) return componentSnapshot;
  const { $figma, ...componentConfig } = componentSnapshot;
  return componentConfig;
}

function isLegacyDoc(markdown) {
  const text = String(markdown || '');
  const normalized = text.toLowerCase();

  if (!text.trim()) return true;
  if (!normalized.includes('## description')) return true;
  if (!normalized.includes('## spec')) return true;
  if (!normalized.includes('## do')) return true;
  if (!normalized.includes('code interactif')) return true;
  if (normalized.includes('<token_mapping>') || normalized.includes('<css>') || normalized.includes('<react>')) return true;
  if (normalized.includes('function buttondemo()')) return true;
  if (normalized.includes('--component-button-color-bg-')) return true;
  if (normalized.includes('card · ${variant} · ${size}')) return true;

  return false;
}

function parseSseJson(raw) {
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const lines = text
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
  const dataLine = lines.find((line) => line.startsWith('data: '));
  if (!dataLine) {
    throw new Error('Reponse MCP invalide: data manquante');
  }
  return JSON.parse(dataLine.slice(6));
}

async function callMcpTool(name, args) {
  const raw = await this.helpers.httpRequest({
    method: 'POST',
    url: MCP_ENDPOINT,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
    },
    body: JSON.stringify({
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'tools/call',
      params: {
        name,
        arguments: args,
      },
    }),
    returnFullResponse: false,
  });

  const payload = parseSseJson(raw);
  return payload.result?.structuredContent || null;
}

async function resolveComponentContext(componentName, tokens, sourceRef) {
  return callMcpTool.call(this, 'get_component_generation_context', {
    name: componentName,
    tokens,
    sourceRef,
  });
}

function referencedTokenPathsFromContext(context) {
  const referencedTokens = Array.isArray(context?.contract?.referencedTokens)
    ? context.contract.referencedTokens
    : [];

  return referencedTokens
    .map((item) => item?.tokenPath)
    .filter(Boolean);
}

function figmaSnapshotFromContext(context) {
  if (!context?.figma?.available) {
    return null;
  }

  return {
    matchedKey: context.figma.matchedKey || null,
    complete: context.figma.complete === true,
    expectedVariantCount: context.figma.expectedVariantCount ?? null,
    actualVariantCount: context.figma.actualVariantCount ?? null,
    blueprint: context.figma.blueprint || null,
    component: {
      htmlTag: context.component?.htmlTag || null,
      rootClass: context.component?.rootClass || null,
      autoDiscovered: context.component?.autoDiscovered === true,
      semanticHtmlKnown: context.component?.semanticHtmlKnown !== false,
      devContractSource: context.component?.devContractSource || null,
      role: context.component?.role || null,
      interactive: context.component?.interactive === true,
      allowedProps: context.component?.allowedProps || [],
      slots: context.component?.slots || [],
      axes: context.component?.axes || {},
      variants: context.component?.variants || [],
      sizes: context.component?.sizes || [],
      states: context.component?.states || [],
      renderRequirements: context.component?.renderRequirements || null,
    },
  };
}

function shouldSkipForFigma(componentName, context) {
  if (!context?.component?.requiresFigma) {
    return null;
  }

  if (!context.figma?.available) {
    return `Figma indisponible pour ${componentName}`;
  }

  if (!context.figma?.complete) {
    return `Cache Figma incomplet pour ${componentName}: ${context.figma?.actualVariantCount || 0}/${context.figma?.expectedVariantCount || '?'}`;
  }

  return null;
}

function parseJsonResponse(value) {
  if (typeof value !== 'string') return value;
  return JSON.parse(value);
}

async function reviewedSourceHashes() {
  // With a capped component batch, main still contains the old docs while a
  // review branch is pending. Scan a small number of recent review branches
  // so each subsequent run picks the next changed component instead of
  // repeatedly paying to regenerate the first one.
  try {
    const refs = parseJsonResponse(await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/tjovy/ds-documentation-thiga/git/matching-refs/heads/ai/',
      headers: { Accept: 'application/vnd.github+json' },
      returnFullResponse: false,
    }));
    const branches = (Array.isArray(refs) ? refs : [])
      .map((entry) => ({
        name: String(entry?.ref || '').replace('refs/heads/', ''),
        sha: entry?.object?.sha || null,
      }))
      .filter((entry) => entry.name.startsWith('ai/') && entry.sha)
      .sort((left, right) => right.name.localeCompare(left.name))
      .slice(0, REVIEW_BRANCH_SCAN_LIMIT);
    const sourceHashes = new Set();
    const figmaHashes = new Set();

    for (const branch of branches) {
      try {
        const content = parseJsonResponse(await this.helpers.httpRequest({
          method: 'GET',
          url: `https://api.github.com/repos/tjovy/ds-documentation-thiga/contents/tokens-docs.json?ref=${encodeURIComponent(branch.sha)}`,
          headers: { Accept: 'application/vnd.github+json' },
          returnFullResponse: false,
        }));
        const encoded = String(content?.content || '').replace(/\s+/g, '');
        if (!encoded) continue;
        const branchDocs = JSON.parse(Buffer.from(encoded, 'base64').toString('utf8'));
        for (const [componentName, entry] of Object.entries(branchDocs?.component || {})) {
          const sourceHash = entry?._meta?.sourceHash;
          if (sourceHash) sourceHashes.add(`${componentName}:${sourceHash}`);
          const figmaHash = entry?._meta?.figmaHash;
          if (
            figmaHash
            && entry?._meta?.workflowVersion === WORKFLOW_VERSION
            && entry?._meta?.rendererVersion === RENDERER_VERSION
          ) {
            figmaHashes.add(`${componentName}:${figmaHash}`);
          }
        }
      } catch (error) {
        console.warn(`Branche de revue ignoree (${branch.name}): ${error.message}`);
      }
    }

    return { sourceHashes, figmaHashes };
  } catch (error) {
    console.warn(`Impossible de lire les branches de revue: ${error.message}`);
    return { sourceHashes: new Set(), figmaHashes: new Set() };
  }
}

try {
  const bufferTokens = await this.helpers.getBinaryDataBuffer(0, 'data', 'Get tokens.json');
  const rawTokens = JSON.parse(bufferTokens.toString('utf8'));
  const tokens = normalizeDesignTokens(rawTokens);
  const sourceRef = $('Get source main ref').first()?.json?.object?.sha || 'main';

  let docs = {};
  try {
    const bufferDocs = await this.helpers.getBinaryDataBuffer(0, 'docs', 'Get tokens-docs.json');
    docs = JSON.parse(bufferDocs.toString('utf8'));
  } catch (error) {
    docs = {};
  }

  const items = [];
  const blockedComponents = [];
  const completedReviews = Number.isFinite(MAX_COMPONENTS_PER_RUN)
    ? await reviewedSourceHashes.call(this)
    : { sourceHashes: new Set(), figmaHashes: new Set() };
  const components = tokens.component || {};
  await callMcpTool.call(this, 'refresh_figma_context', {});
  const inventory = await callMcpTool.call(this, 'list_components', { tokens });
  const componentNames = [...new Set([
    ...Object.keys(components),
    ...(inventory?.components || []).map((component) => component?.name).filter(Boolean),
  ])].sort();

  for (const componentName of componentNames) {
    const existingEntry = docs.component?.[componentName] || {};
    const existingMarkdown = existingEntry.description || '';
    const existingMeta = existingEntry._meta || {};
    const context = await resolveComponentContext.call(this, componentName, tokens, sourceRef);
    const figmaSkipReason = shouldSkipForFigma(componentName, context);
    if (figmaSkipReason) {
      blockedComponents.push({ componentName, reason: figmaSkipReason });
      console.warn(figmaSkipReason);
      continue;
    }
    const metaPaths = Array.isArray(existingMeta?.referencedTokenPaths)
      ? existingMeta.referencedTokenPaths.filter(Boolean)
      : [];
    const referencedTokenPaths = metaPaths.length > 0 ? metaPaths : referencedTokenPathsFromContext(context);

    const componentSnapshot = components[componentName] || {};
    const componentConfig = componentConfigForHash(componentSnapshot);
    const referencedSnapshot = referencedTokenPaths.map((tokenPath) => ({
      tokenPath,
      value: getNodeByPath(tokens, tokenPath),
    }));

    const componentTokenHash = simpleHash(componentConfig);
    const referencedTokenHash = simpleHash(referencedSnapshot);
    const figmaHash = simpleHash(figmaSnapshotFromContext(context));
    const currentSourceHash = simpleHash({
      workflowVersion: WORKFLOW_VERSION,
      rendererVersion: RENDERER_VERSION,
      componentTokenHash,
      referencedTokenHash,
      figmaHash,
    });

    const reasons = [];
    if (isLegacyDoc(existingMarkdown)) reasons.push('legacy_doc');
    if (!existingMeta || typeof existingMeta !== 'object' || !existingMeta.sourceHash) reasons.push('missing_meta');
    if ((existingMeta.workflowVersion || '') !== WORKFLOW_VERSION) reasons.push('workflow_version_changed');
    if ((existingMeta.rendererVersion || '') !== RENDERER_VERSION) reasons.push('renderer_version_changed');
    if (existingMeta.componentTokenHash && existingMeta.componentTokenHash !== componentTokenHash) reasons.push('component_tokens_changed');
    if (referencedTokenPaths.length > 0 && existingMeta.referencedTokenHash && existingMeta.referencedTokenHash !== referencedTokenHash) reasons.push('referenced_tokens_changed');
    if (existingMeta.figmaHash && existingMeta.figmaHash !== figmaHash) reasons.push('figma_blueprint_changed');
    if (existingMeta.sourceHash && existingMeta.sourceHash !== currentSourceHash) reasons.push('source_hash_changed');

    const isMetadataOnlyComponent = isObject(componentSnapshot)
      && Object.keys(componentSnapshot).every((key) => key === '$figma');
    const alreadyReviewed = completedReviews.sourceHashes.has(`${componentName}:${currentSourceHash}`)
      || (isMetadataOnlyComponent && completedReviews.figmaHashes.has(`${componentName}:${figmaHash}`));
    if (reasons.length > 0 && alreadyReviewed) {
      console.log(`${componentName} deja genere dans une branche de revue au meme etat source.`);
      continue;
    }

    if (reasons.length > 0) {
      items.push({
        json: {
          componentName,
          tokenPath: `component.${componentName}`,
          rawComponentTokens: componentSnapshot,
          existingMarkdown,
          previousDocs: docs,
          sourceTokens: tokens,
          sourceRef,
          sourceComparison: {
            workflowVersion: WORKFLOW_VERSION,
            rendererVersion: RENDERER_VERSION,
            reasons,
            componentTokenHash,
            referencedTokenPaths,
            referencedTokenHash,
            figmaHash,
            currentSourceHash,
            previousSourceHash: existingMeta.sourceHash || null,
            previousFigmaHash: existingMeta.figmaHash || null,
          },
        },
      });
    }
  }

  if (!items.length) {
    const blockedMessage = blockedComponents.length
      ? ` Composants bloques sans appel OpenAI: ${JSON.stringify(blockedComponents)}`
      : '';
    console.log(`Aucune difference exploitable entre tokens.json et tokens-docs.json. Aucun appel OpenAI.${blockedMessage}`);
    return [];
  }

  return Number.isFinite(MAX_COMPONENTS_PER_RUN)
    ? items.slice(0, MAX_COMPONENTS_PER_RUN)
    : items;
} catch (error) {
  return [{ json: { error: 'filter_failed', details: error.message } }];
}

const MCP_ENDPOINT = 'http://127.0.0.1:3101/mcp';
const MCP_TOOL_NAME = 'get_component_generation_context';
const MAX_FIGMA_CACHE_AGE_HOURS = Number($env.MAX_FIGMA_CACHE_AGE_HOURS || 168);

function parseSseJson(raw) {
  if (raw && typeof raw === 'object' && !Buffer.isBuffer(raw)) {
    return raw;
  }

  const text = Buffer.isBuffer(raw) ? raw.toString('utf8') : String(raw || '');

  try {
    return JSON.parse(text);
  } catch {
    // SSE fallback handled below.
  }

  const dataChunks = text
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.startsWith('data:'))
    .map((line) => line.slice(5).trim())
    .filter(Boolean)
    .filter((line) => line !== '[DONE]');

  if (!dataChunks.length) {
    throw new Error('Reponse MCP invalide: payload JSON ou data SSE manquant');
  }

  for (let index = dataChunks.length - 1; index >= 0; index -= 1) {
    try {
      return JSON.parse(dataChunks[index]);
    } catch {
      // Keep searching until a valid JSON payload is found.
    }
  }

  throw new Error('Reponse MCP invalide: aucun bloc data SSE JSON exploitable');
}

function extractStructuredContent(payload, toolName) {
  if (!payload || typeof payload !== 'object') {
    throw new Error(`Reponse MCP invalide pour ${toolName}: payload vide`);
  }

  if (payload.error) {
    const message = payload.error.message || JSON.stringify(payload.error);
    throw new Error(`Erreur MCP ${toolName}: ${message}`);
  }

  const result = payload.result;
  if (!result || typeof result !== 'object') {
    throw new Error(`Reponse MCP invalide pour ${toolName}: result manquant`);
  }

  return result.structuredContent ?? null;
}

async function callMcpTool(name, args) {
  const raw = await this.helpers.httpRequest({
    method: 'POST',
    url: MCP_ENDPOINT,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
    },
    body: JSON.stringify({
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'tools/call',
      params: {
        name,
        arguments: args,
      },
    }),
    returnFullResponse: false,
    timeout: 30000,
  });

  const payload = parseSseJson(raw);
  return extractStructuredContent(payload, name);
}

const incomingItems = $input.all();
const outputItems = [];

for (const item of incomingItems) {
  const data = item?.json || {};
  const componentName = String(data.componentName || '').trim();

  if (data.error) {
    throw new Error(`Filtre composants en erreur: ${data.details || data.error}`);
  }

  if (data.stop || !componentName) {
    console.log(data.message || 'Aucun composant a enrichir par le contexte MCP.');
    continue;
  }

  const context = await callMcpTool.call(this, MCP_TOOL_NAME, {
    name: componentName,
    tokens: data.sourceTokens,
    sourceRef: data.sourceRef,
  });

  if (!context || !context.component || !context.component.name) {
    throw new Error(`Contexte MCP incomplet pour ${componentName}`);
  }

  if (String(context.component.name).toLowerCase() !== componentName.toLowerCase()) {
    throw new Error(`Contexte MCP incoherent: demande=${componentName}, reponse=${context.component.name}`);
  }

  if (!context.component.htmlTag || !context.component.rootClass) {
    throw new Error(`Contrat MCP incomplet pour ${componentName}: htmlTag/rootClass manquant`);
  }

  if (context.component.requiresFigma && !context.figma?.available) {
    throw new Error(`Figma indisponible pour ${componentName} alors que le workflow exige un contexte Figma`);
  }

  if (context.component.requiresFigma && !context.figma?.complete) {
    throw new Error(
      `Cache Figma incomplet pour ${componentName}: ${context.figma?.actualVariantCount || 0}/${context.figma?.expectedVariantCount || '?'} variantes`,
    );
  }

  const cachedAt = Date.parse(context.figma?.cachedAt || '');
  const cacheAgeHours = Number.isFinite(cachedAt) ? (Date.now() - cachedAt) / 3600000 : Infinity;
  if (context.component.requiresFigma && cacheAgeHours > MAX_FIGMA_CACHE_AGE_HOURS) {
    throw new Error(`Cache Figma trop ancien pour ${componentName}: ${Math.floor(cacheAgeHours)}h`);
  }

  outputItems.push({
    json: {
      ...data,
      mcpContext: context,
    },
  });
}

return outputItems;

const OPENAI_ENDPOINT = 'https://api.openai.com/v1/responses';
const MCP_ENDPOINT = 'http://127.0.0.1:3101/mcp';
const OPENAI_MODEL = $env.OPENAI_MODEL || 'gpt-5.4-nano';
const OPENAI_REASONING_EFFORT = $env.OPENAI_REASONING_EFFORT || 'none';
const OPENAI_MAX_OUTPUT_TOKENS = Number($env.OPENAI_MAX_OUTPUT_TOKENS || 2500);
const OPENAI_MAX_REPAIR_TOKENS = Number($env.OPENAI_MAX_REPAIR_TOKENS || 1200);
const SYSTEM_PROMPT = "Tu generes la documentation et le code du composant Thiga courant pour `tokens-docs.json` et Storybook `react-live`.\n\nLe workflow peut fournir n'importe quel composant nouveau ou modifie. Tu ne dois jamais limiter ta reponse a Button, Card, ou a une liste de composants connus.\n\nSource unique des informations composant:\n- utilise exclusivement le contexte MCP JSON fourni dans le message utilisateur;\n- n'interprete pas le nom du composant;\n- n'applique pas de convention generique de design system;\n- n'invente aucune variante, taille, etat, prop, slot, valeur, couleur, role, classe, tag HTML ou variable CSS.\n- si `component.semanticHtmlKnown` vaut `false`, n'attribue aucune semantique HTML au composant et mentionne cette limite dans `## Spec`.\n- si `component.devContractSource` est renseigne, utilise `component.htmlTag`, `component.role`, `component.interactive`, `component.allowedProps` et `component.slots` comme contrat developpeur explicite.\n\nSources MCP a suivre, par priorite:\n1. `figma.blueprint`\n2. `component`\n3. `allowedCssVars`\n4. `tokenValues`\n5. `jsxBlueprint`\n\nSi une information manque, ecris la limite dans `## Spec` et n'essaie pas de la completer.\n\nRegles strictes:\n- Utilise uniquement les variables CSS listees dans `allowedCssVars`.\n- Interdit: couleur litterale hex/rgb/hsl, URL, fetch, import, export, acces reseau, acces DOM global.\n- Interdit: fallback CSS du type `var(--x, valeur)`.\n- Interdit: construire dynamiquement un nom de variable CSS; chaque appel `var(--nom)` doit contenir un nom litteral present dans `allowedCssVars`.\n- Interdit: declarer des custom properties locales ou des alias (`--bg`, `--w`, etc.); toute chaine commencant par `--` doit etre exactement un nom de `allowedCssVars`.\n- Pour les matrices, utilise des selecteurs CSS explicites par variante/taille/etat au lieu de transmettre des variables CSS via `style`.\n- Les valeurs numeriques litterales sont autorisees uniquement lorsqu'elles figurent exactement dans `figma.blueprint` (dimensions, rayon, gap, padding, taille ou hauteur de ligne).\n- Si aucun token autorise ne resout exactement la valeur Figma, utilise la valeur numerique Figma plutot qu'une valeur de token approximative.\n- Reproduis exactement les textes et glyphes presents dans `figma.blueprint.textNodes`; ne remplace jamais une icone texte par un autre symbole.\n- Reproduis l'ordre et les positions des variantes du blueprint Figma. N'ajoute aucun titre d'axe, legende, cellule, cadre ou libelle de demonstration absent du composant Figma.\n- Le JSX doit compiler dans `react-live`.\n- Le HTML doit respecter `component.htmlTag`.\n- La classe racine doit etre exactement `component.rootClass`.\n- Le role ARIA, les props et les slots doivent venir uniquement de `component.role`, `component.allowedProps` et `component.slots`.\n- Les axes rendus doivent venir uniquement de `component.axes`, `component.variants`, `component.sizes`, `component.states` ou `figma.blueprint`.\n- Pour un composant auto-detecte, ne deduis rien depuis `component.name`; utilise seulement les champs MCP explicites.\n- Le composant expose une API de developpement compacte issue uniquement de `component.allowedProps` et `component.slots` : ne cree jamais une API par calque Figma (`variantIndex`, classes numerotees, `switch` de calques). La matrice Figma peut utiliser des props de preview internes uniquement dans `Demo`.\n\nRetourne uniquement du Markdown avec exactement ces titres H2, dans cet ordre:\n\n## Description\n1 ou 2 phrases courtes, uniquement d'apres le MCP.\n\n## Spec\n4 a 6 puces factuelles d'apres Figma, axes, exigences de rendu et tokens MCP.\n\n## Do & Don't\n2 ou 3 Do, puis 2 ou 3 Don't, uniquement d'apres `component.usageRules`, `component.accessibility` et `component.renderRequirements`.\n\n## Code interactif (Live Editor)\nUn seul bloc `jsx`.\n\nLe bloc `jsx` doit:\n- commencer par `const css = \\`...\\`;`\n- inclure CSS, helpers si necessaires, composant, puis `const Demo = () => ...`\n- se terminer exactement par `render(<Demo />);`\n- afficher toutes les variantes declarees par le MCP dans l'ordre visuel Figma, avec `.map()` lorsque le blueprint le permet\n- afficher dans chaque variante les contenus exacts du blueprint Figma, jamais le nom technique des axes comme contenu utilisateur\n- verifier avant de repondre chaque exigence exacte de `component.renderRequirements`, notamment glyphes, textes, dimensions et tailles typographiques\n- utiliser `component.htmlTag` comme element racine du composant\n- si `component.htmlTag` vaut `button`, inclure un vrai attribut `disabled` lorsque l'etat MCP le prevoit\n- rester compact: pas de commentaire long, pas de texte marketing, pas de duplication inutile";

function getApiKey() {
  const apiKey = $env.OPENAI_API_KEY;
  if (!apiKey) throw new Error('OPENAI_API_KEY manque dans n8n. Ajoutez-la puis redemarrez n8n.');
  return apiKey;
}

function parseSseJson(raw) {
  if (raw && typeof raw === 'object' && !Buffer.isBuffer(raw)) return raw;
  const text = Buffer.isBuffer(raw) ? raw.toString('utf8') : String(raw || '');
  try { return JSON.parse(text); } catch {}
  const chunks = text.split('\n').map((line) => line.trim()).filter((line) => line.startsWith('data:'));
  for (let index = chunks.length - 1; index >= 0; index -= 1) {
    try { return JSON.parse(chunks[index].slice(5).trim()); } catch {}
  }
  throw new Error('Reponse MCP invalide');
}

async function callMcpTool(name, args) {
  const raw = await this.helpers.httpRequest({
    method: 'POST', url: MCP_ENDPOINT,
    headers: { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' },
    body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: 'tools/call', params: { name, arguments: args } }),
    returnFullResponse: false, timeout: 30000,
  });
  const payload = parseSseJson(raw);
  if (payload.error) throw new Error(payload.error.message || 'Erreur MCP');
  return payload.result?.structuredContent || null;
}

function compactBlueprint(ctx) {
  const blueprint = ctx.figma?.blueprint || {};
  return {
    shell: blueprint.shell,
    axes: blueprint.axes || {},
    variants: blueprint.variants || [],
    textNodes: blueprint.textNodes,
  };
}

function compactContext(ctx = {}) {
  const tokenMap = new Map();
  for (const item of [...(ctx.contract?.componentTokens || []), ...(ctx.contract?.referencedTokens || [])]) {
    if (item?.cssVar) tokenMap.set(item.cssVar, item.resolvedValue);
  }
  const allowedCssVars = Array.isArray(ctx.contract?.allowedCssVars)
    ? ctx.contract.allowedCssVars
    : [...tokenMap.keys()];
  return {
    source: {
      type: 'mcp:get_component_generation_context',
      instruction: 'Do not infer component information outside this JSON payload.',
    },
    component: {
      name: ctx.component?.name, htmlTag: ctx.component?.htmlTag, rootClass: ctx.component?.rootClass,
      autoDiscovered: ctx.component?.autoDiscovered === true,
      semanticHtmlKnown: ctx.component?.semanticHtmlKnown !== false,
      devContractSource: ctx.component?.devContractSource || null,
      role: ctx.component?.role || null,
      interactive: ctx.component?.interactive === true,
      allowedProps: ctx.component?.allowedProps || [],
      slots: ctx.component?.slots || [],
      axes: ctx.component?.axes || {},
      variants: ctx.component?.variants || [], sizes: ctx.component?.sizes || [], states: ctx.component?.states || [],
      previewMatrix: ctx.component?.previewMatrix, renderRequirements: ctx.component?.renderRequirements,
      usageRules: ctx.component?.usageRules, accessibility: ctx.component?.accessibility,
    },
    figma: { matchedKey: ctx.figma?.matchedKey, cachedAt: ctx.figma?.cachedAt, blueprint: compactBlueprint(ctx) },
    allowedCssVars,
    tokenValues: [...tokenMap.entries()],
    jsxBlueprint: ctx.outputRequirements?.jsxBlueprint,
  };
}

function extractOutputText(response) {
  if (typeof response?.output_text === 'string') return response.output_text;
  for (const item of response?.output || []) {
    for (const block of item?.content || []) if (typeof block?.text === 'string') return block.text;
  }
  return '';
}

async function enforceExactPreview(componentName, markdown, data) {
  const normalized = await callMcpTool.call(this, 'enforce_exact_figma_preview', {
    name: componentName,
    markdown,
    tokens: data.sourceTokens,
    sourceRef: data.sourceRef,
  });
  if (normalized?.error) throw new Error(normalized.error);
  return {
    markdown: normalized?.markdown || markdown,
    preview: {
      exact: normalized?.exact === true,
      enforced: normalized?.enforced === true,
      warning: normalized?.warning || null,
    },
  };
}

function retryable(error) {
  const status = Number(error?.statusCode || error?.response?.status || 0);
  const code = error?.response?.data?.error?.code || error?.response?.data?.code || error?.code;
  if (code === 'insufficient_quota' || code === 'invalid_api_key') return false;
  return status === 429 || status >= 500;
}

function retryableOpenAiResponse(response) {
  const status = Number(response?.statusCode || 0);
  const code = response?.body?.error?.code || response?.body?.code;
  if (code === 'insufficient_quota' || code === 'invalid_api_key') return false;
  return status === 429 || status >= 500;
}

function formatDetails(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function formatOpenAiHttpError(response) {
  const status = response?.statusCode || 'unknown';
  const body = response?.body || {};
  const details = body?.error || body;
  return `OpenAI API error ${status}: ${formatDetails(details) || 'reponse vide'}`;
}

function formatOpenAiTransportError(error) {
  const status = error?.statusCode || error?.response?.status || 'unknown';
  const data = error?.response?.data || error?.error || error?.message || null;
  return `OpenAI API transport error ${status}: ${formatDetails(data) || 'requete impossible'}`;
}

async function requestOpenAi(input, maxOutputTokens) {
  const body = {
    model: OPENAI_MODEL, instructions: SYSTEM_PROMPT, input, max_output_tokens: maxOutputTokens,
    reasoning: { effort: OPENAI_REASONING_EFFORT },
  };
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'POST', url: OPENAI_ENDPOINT,
        headers: { Authorization: `Bearer ${getApiKey()}`, 'Content-Type': 'application/json' },
        body, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 180000,
      });
      const status = Number(response?.statusCode || 200);
      if (status >= 400) {
        if (attempt === 0 && retryableOpenAiResponse(response)) {
          await new Promise((resolve) => setTimeout(resolve, 1200));
          continue;
        }
        throw new Error(formatOpenAiHttpError(response));
      }
      return response.body;
    } catch (error) {
      if (String(error?.message || '').startsWith('OpenAI API error ')) throw error;
      if (!retryable(error)) throw new Error(formatOpenAiTransportError(error));
      if (attempt) throw new Error(formatOpenAiTransportError(error));
      await new Promise((resolve) => setTimeout(resolve, 1200));
    }
  }
}

const outputItems = [];
for (const item of $input.all()) {
  const data = item?.json || {};
  const componentName = String(data.componentName || '').trim();
  if (!componentName) continue;
  const compact = compactContext(data.mcpContext || {});
  const firstInput = [
    `Composant: ${componentName}`,
    'Contexte MCP JSON. Utilise uniquement ce JSON. Ne demande aucun outil. Ne complete rien par interpretation.',
    JSON.stringify(compact),
  ].join('\n');
  const firstResponse = await requestOpenAi.call(this, firstInput, OPENAI_MAX_OUTPUT_TOKENS);
  let text = extractOutputText(firstResponse).trim();
  if (!text) throw new Error(`OpenAI n'a retourne aucun markdown pour ${componentName}`);
  let previewResult = await enforceExactPreview.call(this, componentName, text, data);
  text = previewResult.markdown;

  let validation = await callMcpTool.call(this, 'validate_component_markdown', {
    name: componentName, markdown: text, tokens: data.sourceTokens, sourceRef: data.sourceRef,
    allowVisualApproximation: Boolean(previewResult.preview.warning),
  });
  let repairResponse = null;
  if (!validation?.valid) {
    const repairInput = [
      'Corrige uniquement les erreurs ci-dessous et retourne tout le Markdown final, sans explication autour.',
      'Reverifie chaque valeur exacte dans component.renderRequirements et figma.blueprint.',
      'Chaque variable CSS doit etre un appel var(--nom-litteral), jamais un nom construit dynamiquement.',
      'unknownCssVars doit etre vide: supprime tous les alias et toutes les declarations de custom properties locales; utilise des selecteurs CSS explicites.',
      `Erreurs MCP:\n${JSON.stringify(validation?.checks || {})}`,
      `Contexte MCP JSON:\n${JSON.stringify(compact)}`,
      `Sortie invalide:\n${text}`,
    ].join('\n\n');
    repairResponse = await requestOpenAi.call(this, repairInput, OPENAI_MAX_REPAIR_TOKENS);
    text = extractOutputText(repairResponse).trim();
    previewResult = await enforceExactPreview.call(this, componentName, text, data);
    text = previewResult.markdown;
    validation = await callMcpTool.call(this, 'validate_component_markdown', {
      name: componentName, markdown: text, tokens: data.sourceTokens, sourceRef: data.sourceRef,
      allowVisualApproximation: Boolean(previewResult.preview.warning),
    });
  }
  if (!validation?.valid) throw new Error(`Validation finale impossible pour ${componentName}: ${JSON.stringify(validation?.checks || {})}`);

  outputItems.push({ json: {
    text, provider: 'openai', model: OPENAI_MODEL, componentName,
    preview: previewResult.preview,
    repairUsed: !!repairResponse,
    openaiResponseIds: [firstResponse?.id, repairResponse?.id].filter(Boolean),
    usage: [firstResponse?.usage, repairResponse?.usage].filter(Boolean),
  } });
}
return outputItems;

const WORKFLOW_VERSION = 'ssot-v6';
const RENDERER_VERSION = 'figma-tree-v4';
const MCP_ENDPOINT = 'http://127.0.0.1:3101/mcp';
// The done output of Loop Over Items contains the generated result of every iteration.
const generatedItems = $input.all();
const sourceItems = $('Filtrer les composants incomplets').all();
const contextItems = $('Get component generation context').all();

function formatBranchTimestamp() {
  const formatter = new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Paris',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });

  const parts = Object.fromEntries(
    formatter.formatToParts(new Date()).map((part) => [part.type, part.value])
  );

  return `${parts.year}-${parts.month}-${parts.day}-${parts.hour}-${parts.minute}-${parts.second}-${Date.now().toString(36).slice(-5)}`;
}

function parseSseJson(raw) {
  const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
  const lines = text
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
  const dataLine = lines.find((line) => line.startsWith('data: '));
  if (!dataLine) {
    throw new Error('Reponse MCP invalide: data manquante');
  }
  return JSON.parse(dataLine.slice(6));
}

function getModelText(payload) {
  if (!payload) return '';
  if (typeof payload.output_text === 'string') return payload.output_text;
  if (typeof payload.text === 'string') return payload.text;
  if (typeof payload.content === 'string') return payload.content;
  if (Array.isArray(payload.content)) {
    const textBlock = payload.content.find((block) => block?.type === 'text' && typeof block.text === 'string');
    if (textBlock) return textBlock.text;
  }
  if (typeof payload.output === 'string') return payload.output;
  if (Array.isArray(payload.output)) {
    const message = payload.output.find((item) => item?.type === 'message' && Array.isArray(item.content));
    const textBlock = message?.content?.find((block) => typeof block?.text === 'string');
    if (textBlock) return textBlock.text;
  }
  if (payload.message?.content) {
    if (typeof payload.message.content === 'string') return payload.message.content;
    if (Array.isArray(payload.message.content)) {
      const textBlock = payload.message.content.find((block) => block?.type === 'text' && typeof block.text === 'string');
      if (textBlock) return textBlock.text;
    }
  }
  return '';
}

function sanitizeMarkdown(markdown) {
  const text = String(markdown || '').trim();
  if (!text) return '';

  const fenceCount = (text.match(/```/g) || []).length;
  if (fenceCount % 2 === 1) {
    return `${text}\n\`\`\`\n`;
  }

  return text;
}

async function callMcpTool(name, args) {
  const raw = await this.helpers.httpRequest({
    method: 'POST',
    url: MCP_ENDPOINT,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json, text/event-stream',
    },
    body: JSON.stringify({
      jsonrpc: '2.0',
      id: Date.now(),
      method: 'tools/call',
      params: {
        name,
        arguments: args,
      },
    }),
    returnFullResponse: false,
  });

  const payload = parseSseJson(raw);
  return payload.result?.structuredContent || null;
}

function toContextPayload(raw) {
  return raw?.json?.mcpContext ?? raw?.json?.structuredContent ?? raw?.json?.content ?? raw?.json ?? {};
}

const previousDocs = JSON.parse(JSON.stringify(sourceItems[0]?.json?.previousDocs || {}));
if (!previousDocs.component) {
  previousDocs.component = {};
}

const expectedComponents = sourceItems
  .map((item) => item?.json?.componentName)
  .filter(Boolean);
const generatedByComponent = new Map(
  generatedItems
    .map((item) => item?.json || {})
    .filter((item) => item.componentName)
    .map((item) => [item.componentName, item]),
);
const contextByComponent = new Map(
  contextItems
    .map((item) => item?.json || {})
    .filter((item) => item.componentName)
    .map((item) => [item.componentName, item]),
);
const validComponents = [];
const invalidComponents = [];

for (const source of sourceItems) {
  const sourceItem = source?.json || {};
  const componentName = sourceItem.componentName || null;
  const generated = componentName ? generatedByComponent.get(componentName) : null;
  const markdown = sanitizeMarkdown(getModelText(generated));
  const context = toContextPayload(componentName ? contextByComponent.get(componentName) : null);
  const comparison = sourceItem.sourceComparison || {};
  const referencedTokenPaths = comparison.referencedTokenPaths || [];
  const componentTokenHash = comparison.componentTokenHash;
  const referencedTokenHash = comparison.referencedTokenHash;
  const figmaHash = comparison.figmaHash;
  const sourceHash = comparison.currentSourceHash;

  if (!componentName || !markdown) {
    invalidComponents.push({
      componentName: componentName || 'unknown',
      reason: 'empty_markdown',
    });
    continue;
  }

  const validation = await callMcpTool.call(this, 'validate_component_markdown', {
    name: componentName,
    markdown,
    tokens: sourceItem.sourceTokens,
    sourceRef: sourceItem.sourceRef,
    allowVisualApproximation: Boolean(generated?.preview?.warning),
  });

  if (!validation?.valid) {
    invalidComponents.push({
      componentName,
      reason: 'mcp_validation_failed',
      checks: validation?.checks || null,
      markdownPreview: markdown.slice(0, 800),
    });
    continue;
  }

  if (!previousDocs.component[componentName]) {
    previousDocs.component[componentName] = {};
  }

  previousDocs.component[componentName].description = markdown;
  previousDocs.component[componentName]._meta = {
    workflowVersion: WORKFLOW_VERSION,
    rendererVersion: comparison.rendererVersion || RENDERER_VERSION,
    generatedAt: new Date().toISOString(),
    sourceHash,
    componentTokenHash,
    referencedTokenHash,
    figmaHash,
    referencedTokenPaths,
    figmaMatchedKey: context.figma?.matchedKey || null,
    figmaCachedAt: context.figma?.cachedAt || null,
    variableCssSource: 'main:build/css/variables.css',
    notes: sourceItem.sourceComparison?.reasons || [],
    preview: {
      exact: generated?.preview?.exact === true,
      enforced: generated?.preview?.enforced === true,
      warning: generated?.preview?.warning || null,
    },
  };

  validComponents.push(componentName);
}

const missingComponents = expectedComponents.filter((name) => !validComponents.includes(name));

if (invalidComponents.length || missingComponents.length) {
  throw new Error(
    `Validation bloquante: missing=${JSON.stringify(missingComponents)} invalid=${JSON.stringify(invalidComponents)}`,
  );
}

if (!validComponents.length) throw new Error('Aucun composant valide genere. Aucun push GitHub.');

const branchName = `ai/tokens-update-${formatBranchTimestamp()}`;
const previewWarnings = validComponents
  .map((componentName) => ({ componentName, warning: previousDocs.component[componentName]?._meta?.preview?.warning || null }))
  .filter((entry) => entry.warning);

return [
  {
    json: {
      mode: 'production',
      message: previewWarnings.length
        ? 'Validation MCP OK. Des apercus Figma sont a verifier dans Storybook avant la PR.'
        : 'Validation MCP OK. Branche GitHub prete pour review Storybook.',
      updatedComponents: validComponents.length,
      validComponents,
      invalidComponents,
      previewWarnings,
      content: JSON.stringify(previousDocs, null, 2),
      contentBase64: Buffer.from(JSON.stringify(previousDocs, null, 2), 'utf-8').toString('base64'),
      owner: 'tjovy',
      repo: 'ds-documentation-thiga',
      filePath: 'tokens-docs.json',
      baseBranch: 'main',
      baseSha: sourceItems[0]?.json?.sourceRef || null,
      branchName,
      commitMessage: `docs(tokens): refresh ${validComponents.join(', ')}`,
    },
  },
];
